 3	predicate sqrt(x: int, r: int) {
 4	    r*r <= x && (r+1)*(r+1) > x
 5	}
 6	
 7	lemma uniqueSqrt(x: int, r1: int, r2: int)
 8	requires x >= 0 && r1 >= 0 && r2 >= 0;
 9	ensures sqrt(x, r1) && sqrt(x, r2) ==> r1 == r2
10	{}
11	
12	method mySqrt(x: int) returns (res: int)
13	ensures sqrt(x, res);
14	{
15	    var l, r := 0, x;
16	    while (l <= r)
17	    decreases r - l;
18	    invariant l >= 0;
19	    invariant r >= 0;
20	    invariant l*l <= x;
21	    invariant (r+1)*(r+1) > x;
22	    {
23	        var mid := (l + r) / 2;
24	        if (mid * mid <= x && (mid + 1) * (mid + 1) > x) {
25	            return mid;
26	        } else if (mid * mid <= x) {
27	            l := mid + 1;
28	        } else {
29	            r := mid - 1;
30	        }
31	    }
32	}

